{"claims":[{"claim_text":"In 2003, Congress passed and President Bush signed legislation that strengthens Medicare and adds a prescription drug benefit.", "claim_types":["factual_assertion"],"evidence_ids":[1]},{"claim_text":"The new prescription drug benefit will be available to 40 million seniors and people with disabilities on January 1, 2006.", "claim_types":["prediction"],"evidence_ids":[1]},{"claim_text":"Until January 1, 2006, Medicare beneficiaries have access to immediate and significant savings on prescription drugs through Medicare-approved prescription drug discount cards.", "claim_types":["factual_assertion"],"evidence_ids":[1]},{"claim_text":"Since June 1, four million Medicare beneficiaries have enrolled in the prescription drug discount card program.", "claim_types":["factual_assertion"],"evidence_ids":[1]},{"claim_text":"Approximately 100,000 more Medicare beneficiaries enroll in the prescription drug discount card program each week.", "claim_types":["factual_assertion"],"evidence_ids":[1]},{"claim_text":"Seniors are saving up to 30 percent off the retail price of brand name drugs through the prescription drug discount card program.", "claim_types":["factual_assertion"],"evidence_ids":[1]},{"claim_text":"Seniors are saving up to 60 percent off the price of generic drugs through the prescription drug discount card program.", "claim_types":["factual_assertion"],"evidence_ids":[1]},{"claim_text":"Low-income seniors receive $600 this year and next year to assist them with the costs of their prescriptions.", "claim_types":["factual_assertion"],"evidence_ids":[1]},{"claim_text":"Seniors who like the coverage they have today can keep it under the new drug benefit.", "claim_types":["factual_assertion"],"evidence_ids":[2]},{"claim_text":"The new law will encourage employers to continue their retiree health benefits by offering them subsidies for their current plans.", "claim_types":["prediction"],"evidence_ids":[2]},{"claim_text":"The new law gives employers the option to supplement the new Medicare drug benefit in the same way they supplement current Medicare doctor and hospital benefits.", "claim_types":["prediction"],"evidence_ids":[2]}],"unresolved_references":[]}
